a = set([1, 9, 17, 25, 33])
b = set([9, 25, 41, 57, 2])
ops = (list(a | b), list(a & b), list(a - b), list(a ^ b), list(b | a), list(b & a), list(b ^ a))
methods = (list(a.union(b, [100, 4])), list(a.intersection([25, 1, 9])), list(a.intersection(b, [9])), list(a.difference([1], set([33]))), list(a.symmetric_difference([1, 2, 3])))
with_dict = (list(a.union({64: 0, 72: 0})), list(a.difference({1: 0, 9: 0})), list(a.symmetric_difference({1: 0, 50: 0})), list(a.intersection({33: 0, 17: 0})))
same = (list(a | a), list(a & a), list(a - a), list(a ^ a), list(a.union(a)), a.isdisjoint(a))
f = frozenset([3, 11, 19])
mixed = (type(f | a).__name__, type(a | f).__name__, type(f & a).__name__, list(f | a), list(a | f))
empty = (set().union(), list(a.intersection()), list(a.difference()))
big = set(range(0, 64, 3))
big2 = set(range(0, 64, 5))
big_ops = (list(big & big2), list(big2 & big), list(big ^ big2), list(big - big2))

RESULT = (ops, methods, with_dict, same, mixed, empty, big_ops)
